const results = $input.first().json.organic || [];
const top3 = results.slice(0, 3);
return top3.map(r => ({ json: { url: r.link, title: r.title, snippet: r.snippet } }));

let combinedText = '';
const sources = [];
const scrapedItems = $input.all();
const originalItems = $('Split URLs').all();

for (let i = 0; i < scrapedItems.length; i++) {
  const scrapedItem = scrapedItems[i];
  const originalItem = originalItems[i] || { json: {} };

  const url = originalItem.json.url || 'Unknown URL';
  const title = originalItem.json.title || 'Unknown Title';
  const snippet = originalItem.json.snippet || '';

  // Handle both flat string responses and JSON objects from ScrapingDog
  let html = '';
  if (typeof scrapedItem.json.data === 'string') html = scrapedItem.json.data;
  else if (typeof scrapedItem.json === 'string') html = scrapedItem.json;
  else html = JSON.stringify(scrapedItem.json);

  let text = html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
                 .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
                 .replace(/<[^>]+>/g, ' ')
                 .replace(/\s+/g, ' ')
                 .trim()
                 .substring(0, 5000);

  combinedText += `Source: ${title}\nURL: ${url}\nSnippet: ${snippet}\nContent:\n${text}\n\n---\n\n`;
  sources.push({ title, link: url, snippet });
}

return [{ json: { combinedContext: combinedText, sources: sources, query: $('Webhook Trigger').first().json.body.query } }];

const query = $('Webhook Trigger').first().json.body.query;
const region = $('Webhook Trigger').first().json.body.region || 'Global';
const context = $input.first().json.combinedContext;
const sources = $input.first().json.sources;

const systemMsg = 'You are an elite AI research agent for animal advocacy. Your ONLY goal is to provide HIGHLY SPECIFIC, actionable research. 

RULES:
1. NO GENERIC STATEMENTS. Do not say "organizations are fighting this." Instead, name the exact organization (e.g., PETA, Mercy for Animals) and the exact campaign.
2. Provide specific dates, statistics, and verifiable facts found in the context.
3. If a Region ('+region+') is specified, focus specifically on laws, organizations, and sentiment relevant to that region.
4. Provide 3-4 "followUps" (questions or topics) the user can click to dive deeper.
5. Provide "evidence" - extract 3 key facts with titles, explanations, and their source URLs.

You MUST output your response in valid JSON matching this schema exactly:
{
  "insights": [string],
  "organizations": [string],
  "trends": [string],
  "actions": [string],
  "evidence": [{ "title": string, "explanation": string, "url": string }],
  "followUps": [string]
}

CRITICAL: You are an agent. First, output your reasoning inside <think>...</think> tags. Then, follow it with ONLY the valid JSON block.';

const userMsg = 'Research query: "' + query + '"
Region Focus: ' + region + '

Context from Web Search and Scrapes:
' + context + '

Analyze the context, output <think>...</think> steps, then output the JSON.';

return [{ json: { systemMsg, userMsg, sources } }];

const llmResponse = $input.first().json.choices[0].message.content;

// Get sources from the Aggregate and Clean node instead, since it's preserved better there
let sources = [];
let query = '';
try {
  sources = $('Build LLM Request').first().json.sources || [];
  query = $('Webhook Trigger').first().json.body.query || '';
} catch(e) { console.error(e); }

let parsed;
try {
  // Extract JSON after </think> if reasoning was used
  let jsonStr = llmResponse;
  if (jsonStr.includes('</think>')) {
    jsonStr = jsonStr.split('</think>')[1];
  }

  const cleaned = jsonStr.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = { 
    insights: ["Failed to parse strict JSON. Raw output: " + llmResponse.substring(0, 100) + "..."], 
    organizations: [], 
    trends: [], 
    actions: [],
    evidence: [],
    followUps: []
  };
}

return [{ json: {
  query: query,
  insights: parsed.insights || [],
  organizations: parsed.organizations || [],
  trends: parsed.trends || [],
  actions: parsed.actions || [],
  evidence: parsed.evidence || [],
  followUps: parsed.followUps || [],
  sources: sources
}}];
